mapper.delete:
delete from
    ssd_query_template_view_user_cfg
where
    tpl_id = #{tplId}
  and created_by = #{createdBy}

mapper.update:
update
    ssd_query_template_view_user_cfg
set
    view_id = #{defaultViewId}
where
    tpl_id = #{tplId}
  and view_id = #{oldDefaultViewId}
  and is_default = 1

mapper.select:
select view_id from ssd_query_template_view_user_cfg where tpl_id in
#{item}
and created_by = #{userName} and is_default = 1
